import{_ as t,c as o,o as a,ah as s,ao as n,ap as r}from"./chunks/framework.Dq2_gudl.js";const m=JSON.parse(`{"title":"Not One Sparrow Is Forgotten — They Were Never Overlooked","description":"Jesus said not one sparrow falls without your Father knowing. What Matthew and the Psalms say about God's care for animals.","frontmatter":{"title":"Not One Sparrow Is Forgotten — They Were Never Overlooked","description":"Jesus said not one sparrow falls without your Father knowing. What Matthew and the Psalms say about God's care for animals."},"headers":[],"relativePath":"en/pets-in-heaven/not-one-sparrow-forgotten.md","filePath":"en/pets-in-heaven/not-one-sparrow-forgotten.md"}`),i={name:"en/pets-in-heaven/not-one-sparrow-forgotten.md"};function h(l,e,p,d,u,c){return a(),o("div",null,[...e[0]||(e[0]=[s('<div class="pl-quote"><p>“They were just a small animal. Will the world remember them? Or am I the only one who does?”</p><p class="pl-quote-soft">Jesus answered that question once, and His answer is gentler than we expect.</p></div><section class="pl-section"><h2>1. Jesus said: not one sparrow falls without your Father</h2><blockquote><p><strong>Matthew 10:29-31</strong></p><p>&quot;Are not two sparrows sold for a farthing? and one of them shall not fall on the ground without your Father. But the very hairs of your head are all numbered. Fear ye not therefore, ye are of more value than many sparrows.&quot;</p></blockquote><p>In Jesus&#39; day, sparrows were among the cheapest things you could buy — two for a penny. They were the kind of life nobody particularly noticed.</p><p>And Jesus said: <strong>without your Father, not one of them falls to the ground.</strong></p><p>The word “fall” there means death. Jesus is saying that the death of the cheapest little bird is not an unnoticed accident to God. Their passing is seen. It is recorded.</p><p>If your companion was small, the kind of animal the world calls “just an animal” — this verse was written for you. God remembers sparrows. He will not forget yours.</p></section><section class="pl-section"><h2>2. He fed them — not one day was missed</h2><blockquote><p><strong>Psalm 147:9</strong></p><p>&quot;He giveth to the beast his food, and to the young ravens which cry.&quot;</p></blockquote><p>David also wrote:</p><blockquote><p><strong>Psalm 36:6</strong></p><p>&quot;…O LORD, thou preservest man and beast.&quot;</p></blockquote><p>“Man and beast” — the Hebrew word covers wild and domestic animals alike. God puts animals on His list of those He preserves, not as an afterthought but side by side with us.</p><p>What does that mean? It means that from their first day to their last, every meal, every winter, every hour you were away from home, God was watching over them. You thought you were caring for them alone. You were caring for them with God.</p></section><section class="pl-section"><h2>3. They belong to God — and that is the safest place</h2><blockquote><p><strong>Psalm 50:10-11</strong></p><p>&quot;For every beast of the forest is mine, and the cattle upon a thousand hills. I know all the fowls of the mountains: and the wild beasts of the field are mine.&quot;</p></blockquote><p>God says: “Every beast of the forest is mine. The cattle on a thousand hills. I know every bird in the mountains.”</p><p>Your pet was never property you owned. They were a gift God entrusted to your care. And when the giver of a gift takes it back, He does not throw it away — He <strong>brings it home to Himself</strong>.</p><p>You don&#39;t know how He cares for them now, where they are, or whether they remember your voice. But you know whose hands they are in: the hands that numbered the sparrows.</p><p class="pl-quote-soft">If you can only hold one sentence today, hold this one:</p></section><div class="pl-quote"><p>“They never left God&#39;s sight. Not even now.”</p></div><section class="pl-section"><h2>A prayer you can try</h2><p>“Lord, thank You for trusting them to me for those years.<br>Thank You for watching over them where I couldn&#39;t see.<br>I can&#39;t hold them anymore, but I know Your hands are bigger than mine.<br>Please care for them, the way You care for every sparrow.<br>And please care for me, because I miss them so much. Amen.”</p><p><a href="/en/pets-in-heaven/">← Back to Pets in Heaven</a> ｜ Next: <a href="/en/pets-in-heaven/rainbow-bridge-covenant">Beyond the Rainbow Bridge</a></p></section><div class="pl-cta"><h2>They have a name.</h2><p>Write their name and one small habit only you knew about. Those details deserve to be kept.</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">Download on the App Store</a></div><div class="pl-bible"><h3>Let the words of Scripture stay with you</h3><p>Every verse in this article comes from the Bible. With Rainbow Bible you can read Scripture anytime and set a daily verse widget — a small light for the days you miss them.</p><div class="pl-bible-shots"><figure><img src="'+n+'" alt="Rainbow Bible home-screen widget showing 2 Timothy 2:13" loading="lazy"><figcaption>Daily verse on your Home Screen</figcaption></figure><figure><img src="'+r+'" alt="Rainbow Bible app — Pets in Heaven topic showing Matthew 10:29-31" loading="lazy"><figcaption>Read Scripture in the Pets in Heaven topic</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">Get Rainbow Bible on the App Store</a></div>',8)])])}const f=t(i,[["render",h]]);export{m as __pageData,f as default};
